export type DynamicBondingCurvePluginPdas = {
  base: typeof findBasePda;
  operator: typeof findOperatorPda;
  partnerMetadata: typeof findPartnerMetadataPda;
  tokenBadge: typeof findTokenBadgePda;
  virtualPoolMetadata: typeof findVirtualPoolMetadataPda;
  baseVault: typeof findBaseVaultPda;
  quoteVault: typeof findQuoteVaultPda;
  migrationMetadata: typeof findMigrationMetadataPda;
};

export type DynamicBondingCurvePluginRequirements = ClientWithRpc<
  GetAccountInfoApi & GetMultipleAccountsApi
> &
  ClientWithPayer &
  ClientWithTransactionPlanning &
  ClientWithTransactionSending;

export function dynamicBondingCurveProgram(
  config: { programAddress?: Address | HasAddress } = {},
) {
  return <T extends DynamicBondingCurvePluginRequirements>(
    client: T,
  ): ExtendedClient<T, { dynamicBondingCurve: DynamicBondingCurvePlugin }> => {
    return extendClient(client, {
      dynamicBondingCurve: <DynamicBondingCurvePlugin>{
        accounts: {
          claimFeeOperator: addSelfFetchFunctions(
            client,
            getClaimFeeOperatorCodec(),
          ),
          configWithTransferHook: addSelfFetchFunctions(
            client,
            getConfigWithTransferHookCodec(),
          ),
          meteoraDammMigrationMetadata: addSelfFetchFunctions(
            client,
            getMeteoraDammMigrationMetadataCodec(),
          ),
          operator: addSelfFetchFunctions(client, getOperatorCodec()),
          partnerMetadata: addSelfFetchFunctions(
            client,
            getPartnerMetadataCodec(),
          ),
          poolConfig: addSelfFetchFunctions(client, getPoolConfigCodec()),
          tokenBadge: addSelfFetchFunctions(client, getTokenBadgeCodec()),
          transferHookPool: addSelfFetchFunctions(
            client,
            getTransferHookPoolCodec(),
          ),
          virtualPool: addSelfFetchFunctions(client, getVirtualPoolCodec()),
          virtualPoolMetadata: addSelfFetchFunctions(
            client,
            getVirtualPoolMetadataCodec(),
          ),
        },
        instructions: {
          claimCreatorTradingFee: (input, instructionConfig) =>
            addSelfPlanAndSendFunctions(
              client,
              getClaimCreatorTradingFeeInstruction(input, {
                programAddress:
                  instructionConfig?.programAddress ?? config.programAddress,
              }),
            ),
          claimCreatorTradingFee2: (input, instructionConfig) =>
            addSelfPlanAndSendFunctions(
              client,
              getClaimCreatorTradingFee2Instruction(input, {
                programAddress:
                  instructionConfig?.programAddress ?? config.programAddress,
              }),
            ),
          claimPartnerPoolCreationFee: (input, instructionConfig) =>
            addSelfPlanAndSendFunctions(
              client,
              getClaimPartnerPoolCreationFeeInstruction(input, {
                programAddress:
                  instructionConfig?.programAddress ?? config.programAddress,
              }),
            ),
          claimProtocolFee2: (input, instructionConfig) =>
            addSelfPlanAndSendFunctions(
              client,
              getClaimProtocolFee2Instruction(input, {
                programAddress:
                  instructionConfig?.programAddress ?? config.programAddress,
              }),
            ),
          claimProtocolPoolCreationFee: (input, instructionConfig) =>
            addSelfPlanAndSendFunctions(
              client,
              getClaimProtocolPoolCreationFeeInstruction(input, {
                programAddress:
                  instructionConfig?.programAddress ?? config.programAddress,
              }),
            ),
          claimTradingFee: (input, instructionConfig) =>
            addSelfPlanAndSendFunctions(
              client,
              getClaimTradingFeeInstruction(input, {
                programAddress:
                  instructionConfig?.programAddress ?? config.programAddress,
              }),
            ),
          claimTradingFee2: (input, instructionConfig) =>
            addSelfPlanAndSendFunctions(
              client,
              getClaimTradingFee2Instruction(input, {
                programAddress:
                  instructionConfig?.programAddress ?? config.programAddress,
              }),
            ),
          closeClaimProtocolFeeOperator: (input, instructionConfig) =>
            addSelfPlanAndSendFunctions(
              client,
              getCloseClaimProtocolFeeOperatorInstruction(input, {
                programAddress:
                  instructionConfig?.programAddress ?? config.programAddress,
              }),
            ),
          closeOperatorAccount: (input, instructionConfig) =>
            addSelfPlanAndSendFunctions(
              client,
              getCloseOperatorAccountInstruction(input, {
                programAddress:
                  instructionConfig?.programAddress ?? config.programAddress,
              }),
            ),
          closeTokenBadge: (input, instructionConfig) =>
            addSelfPlanAndSendFunctions(
              client,
              getCloseTokenBadgeInstruction(input, {
                programAddress:
                  instructionConfig?.programAddress ?? config.programAddress,
              }),
            ),
          createConfig: (input, instructionConfig) =>
            addSelfPlanAndSendFunctions(
              client,
              getCreateConfigInstruction(
                { ...input, payer: input.payer ?? client.payer },
                {
                  programAddress:
                    instructionConfig?.programAddress ?? config.programAddress,
                },
              ),
            ),
          createConfig2: (input, instructionConfig) =>
            addSelfPlanAndSendFunctions(
              client,
              getCreateConfig2Instruction(
                { ...input, payer: input.payer ?? client.payer },
                {
                  programAddress:
                    instructionConfig?.programAddress ?? config.programAddress,
                },
              ),
            ),
          createConfigWithTransferHook: (input, instructionConfig) =>
            addSelfPlanAndSendFunctions(
              client,
              getCreateConfigWithTransferHookInstruction(
                { ...input, payer: input.payer ?? client.payer },
                {
                  programAddress:
                    instructionConfig?.programAddress ?? config.programAddress,
                },
              ),
            ),
          createLocker: (input, instructionConfig) =>
            addSelfPlanAndSendFunctions(
              client,
              getCreateLockerInstructionAsync(
                { ...input, payer: input.payer ?? client.payer },
                {
                  programAddress:
                    instructionConfig?.programAddress ?? config.programAddress,
                },
              ),
            ),
          createOperatorAccount: (input, instructionConfig) =>
            addSelfPlanAndSendFunctions(
              client,
              getCreateOperatorAccountInstructionAsync(
                { ...input, payer: input.payer ?? client.payer },
                {
                  programAddress:
                    instructionConfig?.programAddress ?? config.programAddress,
                },
              ),
            ),
          createPartnerMetadata: (input, instructionConfig) =>
            addSelfPlanAndSendFunctions(
              client,
              getCreatePartnerMetadataInstructionAsync(
                { ...input, payer: input.payer ?? client.payer },
                {
                  programAddress:
                    instructionConfig?.programAddress ?? config.programAddress,
                },
              ),
            ),
          createTokenBadge: (input, instructionConfig) =>
            addSelfPlanAndSendFunctions(
              client,
              getCreateTokenBadgeInstructionAsync(
                { ...input, payer: input.payer ?? client.payer },
                {
                  programAddress:
                    instructionConfig?.programAddress ?? config.programAddress,
                },
              ),
            ),
          createVirtualPoolMetadata: (input, instructionConfig) =>
            addSelfPlanAndSendFunctions(
              client,
              getCreateVirtualPoolMetadataInstructionAsync(
                { ...input, payer: input.payer ?? client.payer },
                {
                  programAddress:
                    instructionConfig?.programAddress ?? config.programAddress,
                },
              ),
            ),
          creatorWithdrawSurplus: (input, instructionConfig) =>
            addSelfPlanAndSendFunctions(
              client,
              getCreatorWithdrawSurplusInstruction(input, {
                programAddress:
                  instructionConfig?.programAddress ?? config.programAddress,
              }),
            ),
          initializeVirtualPoolWithSplToken: (input, instructionConfig) =>
            addSelfPlanAndSendFunctions(
              client,
              getInitializeVirtualPoolWithSplTokenInstructionAsync(
                { ...input, payer: input.payer ?? client.payer },
                {
                  programAddress:
                    instructionConfig?.programAddress ?? config.programAddress,
                },
              ),
            ),
          initializeVirtualPoolWithToken2022: (input, instructionConfig) =>
            addSelfPlanAndSendFunctions(
              client,
              getInitializeVirtualPoolWithToken2022InstructionAsync(
                { ...input, payer: input.payer ?? client.payer },
                {
                  programAddress:
                    instructionConfig?.programAddress ?? config.programAddress,
                },
              ),
            ),
          initializeVirtualPoolWithToken2022TransferHook: (
            input,
            instructionConfig,
          ) =>
            addSelfPlanAndSendFunctions(
              client,
              getInitializeVirtualPoolWithToken2022TransferHookInstructionAsync(
                { ...input, payer: input.payer ?? client.payer },
                {
                  programAddress:
                    instructionConfig?.programAddress ?? config.programAddress,
                },
              ),
            ),
          migrateMeteoraDamm: (input, instructionConfig) =>
            addSelfPlanAndSendFunctions(
              client,
              getMigrateMeteoraDammInstruction(
                { ...input, payer: input.payer ?? client.payer },
                {
                  programAddress:
                    instructionConfig?.programAddress ?? config.programAddress,
                },
              ),
            ),
          migrateMeteoraDammClaimLpToken: (input, instructionConfig) =>
            addSelfPlanAndSendFunctions(
              client,
              getMigrateMeteoraDammClaimLpTokenInstructionAsync(input, {
                programAddress:
                  instructionConfig?.programAddress ?? config.programAddress,
              }),
            ),
          migrateMeteoraDammLockLpToken: (input, instructionConfig) =>
            addSelfPlanAndSendFunctions(
              client,
              getMigrateMeteoraDammLockLpTokenInstructionAsync(input, {
                programAddress:
                  instructionConfig?.programAddress ?? config.programAddress,
              }),
            ),
          migrationDammV2: (input, instructionConfig) =>
            addSelfPlanAndSendFunctions(
              client,
              getMigrationDammV2Instruction(
                { ...input, payer: input.payer ?? client.payer },
                {
                  programAddress:
                    instructionConfig?.programAddress ?? config.programAddress,
                },
              ),
            ),
          migrationDammV2CreateMetadata: (input, instructionConfig) =>
            addSelfPlanAndSendFunctions(
              client,
              getMigrationDammV2CreateMetadataInstruction(
                { ...input, payer: input.payer ?? client.payer.address },
                {
                  programAddress:
                    instructionConfig?.programAddress ?? config.programAddress,
                },
              ),
            ),
          migrationMeteoraDammCreateMetadata: (input, instructionConfig) =>
            addSelfPlanAndSendFunctions(
              client,
              getMigrationMeteoraDammCreateMetadataInstructionAsync(
                { ...input, payer: input.payer ?? client.payer },
                {
                  programAddress:
                    instructionConfig?.programAddress ?? config.programAddress,
                },
              ),
            ),
          partnerWithdrawSurplus: (input, instructionConfig) =>
            addSelfPlanAndSendFunctions(
              client,
              getPartnerWithdrawSurplusInstruction(input, {
                programAddress:
                  instructionConfig?.programAddress ?? config.programAddress,
              }),
            ),
          swap: (input, instructionConfig) =>
            addSelfPlanAndSendFunctions(
              client,
              getSwapInstruction(
                { ...input, payer: input.payer ?? client.payer },
                {
                  programAddress:
                    instructionConfig?.programAddress ?? config.programAddress,
                },
              ),
            ),
          swap2: (input, instructionConfig) =>
            addSelfPlanAndSendFunctions(
              client,
              getSwap2Instruction(
                { ...input, payer: input.payer ?? client.payer },
                {
                  programAddress:
                    instructionConfig?.programAddress ?? config.programAddress,
                },
              ),
            ),
          swap2WithTransferHook: (input, instructionConfig) =>
            addSelfPlanAndSendFunctions(
              client,
              getSwap2WithTransferHookInstruction(
                { ...input, payer: input.payer ?? client.payer },
                {
                  programAddress:
                    instructionConfig?.programAddress ?? config.programAddress,
                },
              ),
            ),
          transferPoolCreator: (input, instructionConfig) =>
            addSelfPlanAndSendFunctions(
              client,
              getTransferPoolCreatorInstruction(input, {
                programAddress:
                  instructionConfig?.programAddress ?? config.programAddress,
              }),
            ),
          withdrawLeftover: (input, instructionConfig) =>
            addSelfPlanAndSendFunctions(
              client,
              getWithdrawLeftoverInstructionAsync(input, {
                programAddress:
                  instructionConfig?.programAddress ?? config.programAddress,
              }),
            ),
          withdrawMigrationFee: (input, instructionConfig) =>
            addSelfPlanAndSendFunctions(
              client,
              getWithdrawMigrationFeeInstruction(input, {
                programAddress:
                  instructionConfig?.programAddress ?? config.programAddress,
              }),
            ),
        },
        pdas: {
          base: (seeds, pdaConfig) =>
            findBasePda(seeds, {
              programAddress:
                pdaConfig?.programAddress ?? config.programAddress,
            }),
          operator: (seeds, pdaConfig) =>
            findOperatorPda(seeds, {
              programAddress:
                pdaConfig?.programAddress ?? config.programAddress,
            }),
          partnerMetadata: (seeds, pdaConfig) =>
            findPartnerMetadataPda(seeds, {
              programAddress:
                pdaConfig?.programAddress ?? config.programAddress,
            }),
          tokenBadge: (seeds, pdaConfig) =>
            findTokenBadgePda(seeds, {
              programAddress:
                pdaConfig?.programAddress ?? config.programAddress,
            }),
          virtualPoolMetadata: (seeds, pdaConfig) =>
            findVirtualPoolMetadataPda(seeds, {
              programAddress:
                pdaConfig?.programAddress ?? config.programAddress,
            }),
          baseVault: (seeds, pdaConfig) =>
            findBaseVaultPda(seeds, {
              programAddress:
                pdaConfig?.programAddress ?? config.programAddress,
            }),
          quoteVault: (seeds, pdaConfig) =>
            findQuoteVaultPda(seeds, {
              programAddress:
                pdaConfig?.programAddress ?? config.programAddress,
            }),
          migrationMetadata: (seeds, pdaConfig) =>
            findMigrationMetadataPda(seeds, {
              programAddress:
                pdaConfig?.programAddress ?? config.programAddress,
            }),
        },
        identifyAccount: identifyDynamicBondingCurveAccount,
        identifyInstruction: identifyDynamicBondingCurveInstruction,
        parseInstruction: parseDynamicBondingCurveInstruction,
      },
    });
  };
}

type MakeOptional<T, K extends keyof T> = Omit<T, K> & Partial<Pick<T, K>>;
